                let row = &row;
                crate::columnar::ArrowValue::append(
                    &row.r#connection_id,
                    columns[0usize].as_mut(),
                )?;
                crate::columnar::ArrowValue::append(
                    &row.r#from_port_id,
                    columns[1usize].as_mut(),
                )?;
                crate::columnar::ArrowValue::append(
                    &row.r#to_port_id,
                    columns[2usize].as_mut(),
                )?;
                crate::columnar::ArrowValue::append(
                    &row.r#rule_template_id,
                    columns[3usize].as_mut(),
                )?;
                crate::columnar::ArrowValue::append(
                    &row.r#tear_cost,
                    columns[4usize].as_mut(),
                )?;
                crate::columnar::ArrowValue::append(
                    &row.r#doc,
                    columns[5usize].as_mut(),
                )?;
